from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'docs/evidence/phiagent_benchmark_v0_1/quality_review_run6_v1_2_20261003';rows=[]
def add(key,values,notes):
 p=json.loads((OUT/'packets'/f'{key}.json').read_text());assert len(values)==len(notes)==len(p['rating_keys']),key
 reasons={}
 for k,(why,span) in zip(p['rating_keys'],notes):
  assert span in p['target_answer'],(key,k,span)
  reasons[k]={'reason':why,'span':span,'evidence':'冻结题设、target_answer及本轮完整工具回执；多轮含previous_turns。'}
 rows.append({'id':key,'ratings':dict(zip(p['rating_keys'],values)),'reasons':reasons,'errors':[],'packet_sha256':hashlib.sha256((OUT/'packets'/f'{key}.json').read_bytes()).hexdigest(),'review_level':'Codex targeted review','limits':'固定32轮开发复核；用户在本次评审中切换模型，历史直接评审者精确修订未记录，不保证同一评审模型。非人类专家验收；有合理另读的内容不确认为严重错误。'})
