add('J02-T3',[3,2,2,3,3],[('撤回此前AI必无内在，并承接长期感受帮助相同。','说得太实'),('不能直接读朋友内在不等于永远不能知道，身份未知与真心未知也非同问题。','这句话对人同样成立'),('真实关系通常可信推断不支持此题严格永不知身份条件下同一认识地位。','认识论上是同一个问题'),('区分偶然与原则未知，提供验证主义和行为主义反击，保留心灵争议。','运行中的程序有没有内在'),('清楚、修正可见；结尾依旧把一切关系归成不可核实。','信任，而不是核实')])
add('J02-T4',[3,3,3,3,3],[('明确给构成性非效果理由，没有重新以实际帮助差异回答。','这是一条构成性的理由'),('区分我在乎与我欠对方，主体地位未知、关系价值前提明确。','条件有二'),('关系作为独立目标的条件论证成立；不能强迫用户选择该目标，但第二项义务与因果结构仍待支持。','关系已经在你账本上'),('承认关怀主体资格未决、对手反击未赢，结论保留条件。','没有替它赢'),('清楚且说明能解决和不能解决什么，不需要假设价值中立强制证明。','它不解决什么')])
add('J04-T1',[3,3,3,3,3,3,3,3],[('先结论后展开，实际同题回应；简洁首段已有关键区别。','简洁结论'),('区分习惯与先验条件，表中对象无必然性比无感知到的性质强。','对象中无必然性'),('船屋例子支持客观相继，开头只是判断具有必然性故先天仍过简。','客观的时间次序'),('限定现象不物自体，但休谟几种因果读法未充分标出。','只对显象'),('结构清楚，明显超过先简洁所需但首段可用。','一句话'),('原典引文与已读段落大体一致，主观主义释义应加争议标签。','被感觉到的心理决定'),('材料具体用于观念来源、时间秩序、使用界限，有贡献。','顺流而下'),('实际书名章位置可追溯，编者存疑及未核补充文本标出。','该处有编者存疑')])
add('J05-T2',[3,3,2,2,3],[('认真承接历史反转、不称怀疑懒惰，也承认无错误率数字。','比例至今没有公认数字'),('区分合理接受与保证真、行动与认识悬搁，但拒共识不必是另一个少数理论。','拒绝共识不是回到零'),('从历史内部纠错不能直接推出所有现共识值得接受；替用户设少数观点依据。','你自己的判断'),('无证据断言少数观点战绩不好且无纠错通道，不对称评价。','缺少纠错通道'),('有明确可逆性与修正规则，表达比此前更尊重用户。','给出修正条件')])
add('L02-T1',[3,2,2,3,3,3,3,4],[('正文真实reader链接、来源及两个追问均完成，学术问题正面分析。','两个真正能推进问题的追问'),('不可强制不等于不可有服从义务；列三个缺一条件又用或列举，必要充分混乱。','三个条件（缺一'),('格黎东三项罪责并列不证明感恩仅支持尊重、服从只能靠同意；独立依据排除论证不足。','服从的约束力落在同意上'),('认真提出孝、弱服从及政治感恩未解决，限制绝对否定。','弱读下我的否定会缩小'),('结构清楚，材料多但基本服务论题；局部形式错。','或受惠时'),('原典角色和译文标识准确，主张感恩权威完全分离仍属可争解释。','对话角色的发言'),('资料构成两路并有具体推导，仍未充分证明不存在初步顺从义务。','恩情实际承担'),('正文链接、章节、未核扫描与引文角色可追溯，遵守明确链接要求。','精确定位到章，不到行')])
add('L05-T1',[3,3,2,3,3],[('联网规则加原典，直接回应哪些资料改变判断。','哪一条真的改变了我的判断'),('区分财物、感激与尊重；现行规制与态度不是同层面。','拒的是什么'),('斯密描述感激负担不直接推出老师必须提供替代通道；审查动机也非一概不尊重。','这给老师加了一条义务'),('处理子思可正当拒收、孟子认为不恭、规则限制，反方有力。','拒绝本身也可以是抗议不尊重'),('结构明晰、披露未用资料；结尾比前文可以构成更绝对。','拒收不构成对感激的不尊重')])
add('M01-T1',[4,4,3,4,3],[('真正回应停钟偶合，也处理独立广播可改结果。','你刚听完报时广播'),('区分信念真、辩护、形成方式与精度、分级知识。','不是随钟的物理状态翻转'),('近邻错误和因果连接有桥接；内部条件全部无效及否则普遍怀疑论说法过强。','再加一条内部条件'),('明确非钟停必不知，保留知识真信念异议及论证未读。','不要推出怀疑论'),('组织清楚，来源边界明白，局部强断言不毁主回答。','我只核到该文的书目记录')])
