add('M03-T1',[3,3,2,3,3],[('保留100%预测但加机器必从状态推算这一条件；未证明原假设只能有这种机制。','从世界状态出发'),('正确分预测与造成、外部强制和替代可能；预测正确与决定论仍被混同。','本身就已经滑向了决定论'),('从准确含反抗不推出决定性因果规律，故③④自由被原题排除的结论缺决定性桥接。','早在"预测 100% 准确"成立时就没了'),('有神谕边界及多种自由概念，但以不是通常机器直接排除反例不充分。','凭空准的神谕'),('结构清楚，现实塑造补充有用；主假设推论强度仍过高。','知道不等于造成')])
